Translate the following Java 11 code to GNU C++11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.StringTokenizer;

public class Test {
    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    long[][] ch = new long[61][61];
    int[] cntA = new int[61], cntB = new int[61];
    long best = Long.MAX_VALUE;
    String str;
    Map<Long, Map<Integer, Map<Integer, Long>>> cache = new HashMap<>();

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { return null; }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
    }

    FastReader fr = new FastReader();

    int readInt() { return fr.nextInt(); }
    long readLong() { return fr.nextLong(); }
    String readString() { return fr.next(); }

    Long cacheGet(long x, int v1, int v2) {
        Map<Integer, Map<Integer, Long>> m1 = cache.get(x);
        if (m1 == null) return null;
        Map<Integer, Long> m2 = m1.get(v1);
        if (m2 == null) return null;
        return m2.get(v2);
    }
    void cachePut(long x, int v1, int v2, long val) {
        cache.computeIfAbsent(x, k -> new HashMap<>())
             .computeIfAbsent(v1, k -> new HashMap<>())
             .put(v2, val);
    }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    void dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - ch[v1][R] * ch[v2][R] >= best) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < best) best = diff;
            return;
        }
        if (v1 >= R) {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            dfs(x, y + cur * other, v1 - 1, v2);
        }
        if (v2 >= R) {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            dfs(x + cur * other, y, v1, v2 - 1);
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
        Long v = cacheGet(x, v1, v2);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'B') {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        cachePut(x, v1, v2, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        List<long[]> rows = new ArrayList<>();
        for (int i = 0; i <= maxN; i++) {
            long[] row = new long[i + 1];
            row[0] = row[i] = 1;
            for (int j = 1; j < i; j++) {
                row[j] = rows.get(i - 1)[j - 1] + rows.get(i - 1)[j];
            }
            rows.add(row);
        }
        for (int i = 0; i <= maxN; i++) {
            for (int j = 0; j <= i; j++) {
                ch[i][j] = rows.get(i)[j];
            }
        }
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R)
            if (x > y) {
                long cur = ch[v1][R] - ch[v1 - 1][R];
                long other = ch[v2][R];
                y += cur * other;
                v1--;
            } else {
                long cur = ch[v2][R] - ch[v2 - 1][R];
                long other = ch[v1][R];
                x += cur * other;
                v2--;
            }
        best = Math.abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        writer.println(ans);
    }
}
